mapper.insert:
insert into novel_generation_task(
	project_id, task_type, status, progress, input_params, create_by, create_time
)values(
	#{projectId}, #{taskType}, #{status}, #{progress}, #{inputParams}, #{createBy}, sysdate()
)

mapper.update:
update novel_generation_task
status = #{status}, progress = #{progress}, result_ref = #{resultRef}, error_msg = #{errorMsg}, start_time = #{startTime}, finish_time = #{finishTime},
where task_id = #{taskId}
